package gg.rsmod.plugins.content.skills.summoning

import java.io.File

/**
 * K02 N397 N370 N377 N386 N389 N392 N395 N396 N398 (owner 2026-10-24/25: the OSRS pets' chat heads and Follower Details heads moved
 * "raar"): an OSRS pet head is not a human head, so it never plays the human dialogue poses (588-617 / 98xx) - those bent the hydra,
 * nightmare and golem heads out of shape. A pet form with its own OSRS chathead sequence plays that one, in the chat and in
 * Follower Details alike; every other OSRS pet head stays still.
 *
 * Data: `data/cfg/pets/pet_chatheads.tsv` (generated by `OsrsPetImportTool table` from `OsrsPetImportTool.CHATHEADS`; the
 * sequences are imported by `OsrsFxImportTool` batch "pet-chatheads", ids and names from RuneLite gameval AnimationID).
 */
object PetChatheads {
    const val TABLE_PATH = "./data/cfg/pets/pet_chatheads.tsv"

    /** No head animation: the client draws the model in its resting pose (IF_SETMODELANIM -1). */
    const val STILL = -1

    @Volatile
    private var talk: Map<Int, Int> = emptyMap()

    fun parse(lines: List<String>): Map<Int, Int> =
        lines.filter { it.isNotBlank() && !it.startsWith("#") }.associate { line ->
            val c = line.split('\t')
            c[0].trim().toInt() to c[1].trim().toInt()
        }

    fun load(file: File = File(TABLE_PATH)): Int {
        if (!file.exists()) return 0
        talk = parse(file.readLines())
        return talk.size
    }

    /**
     * OSRS pets that keep the human dialogue poses: Pet Zilyana has a human head, and the owner called the Bloodhound's talking
     * head right (N388, 2026-10-25: "chat-animatie wel").
     */
    val HUMAN_POSE = setOf("Pet Zilyana", "Bloodhound")

    /** An OSRS pet follower (not one of the 667 pets, whose creature heads have the cache's own pose). */
    fun isOsrsPet(npcId: Int): Boolean = Pets.variantOfNpc(npcId)?.classic == false

    fun humanPose(npcId: Int): Boolean = Pets.variantOfNpc(npcId)?.let { !it.classic && it.name in HUMAN_POSE } == true

    /** The head animation of OSRS pet [npcId]: its own OSRS chathead sequence, else [STILL]; null for any other npc and the [HUMAN_POSE] pets. */
    fun animation(npcId: Int): Int? = if (isOsrsPet(npcId) && !humanPose(npcId)) talk[npcId] ?: STILL else null

    /** Follower Details: the same head movement as in the chat ([HUMAN_POSE] pets the plain talking pose); null = still. */
    fun panelAnimation(npcId: Int): Int? =
        if (humanPose(npcId)) gg.rsmod.plugins.api.cfg.FacialExpression.NORMAL.classic else animation(npcId)?.takeIf { it != STILL }
}
